import Foundation

// A complete recipe SnapCal can present and step through. Generated by
// RecipeGenerator (Foundation Models on-device → USDA nutrition compute)
// or fetched from a saved set. The struct is the boundary between the
// model's generative output and everything the UI/persistence sees —
// once we have one, the source no longer matters.
struct Recipe: Codable, Sendable, Identifiable, Hashable {
    let id: UUID
    var name: String
    var summary: String           // one-sentence pitch ("Hearty 20-min skillet with whatever protein you've got.")
    var symbol: String            // SF Symbol used as the visual ID for the recipe (no stock photos in v1)
    var palette: RecipePalette    // gradient pair driving the card hero color
    var servings: Int
    var prepMinutes: Int
    var cookMinutes: Int
    var difficulty: RecipeDifficulty
    var ingredients: [RecipeIngredient]
    var steps: [RecipeStep]
    var perServing: NutritionFacts        // computed by USDA after generation
    var sourceTag: String                 // "foundation-models", "gemini", "saved", etc.
    var createdAt: Date

    var totalMinutes: Int { prepMinutes + cookMinutes }
}

struct RecipeIngredient: Codable, Sendable, Identifiable, Hashable {
    let id: UUID
    var name: String              // canonical name used for USDA lookup ("chicken breast, raw")
    var displayName: String       // what we show in the UI ("Chicken breast")
    var quantity: Double
    var unit: String              // freeform — "g", "oz", "tbsp", "cloves", "to taste"
    var fromPantry: Bool          // true if a pantry item matched at generation time
    var perServing: NutritionFacts?

    init(
        id: UUID = UUID(),
        name: String,
        displayName: String,
        quantity: Double,
        unit: String,
        fromPantry: Bool = false,
        perServing: NutritionFacts? = nil
    ) {
        self.id = id
        self.name = name
        self.displayName = displayName
        self.quantity = quantity
        self.unit = unit
        self.fromPantry = fromPantry
        self.perServing = perServing
    }
}

struct RecipeStep: Codable, Sendable, Identifiable, Hashable {
    let id: UUID
    var index: Int                // 1-based for display
    var instruction: String
    var timerSeconds: Int?        // nil = no built-in timer

    init(id: UUID = UUID(), index: Int, instruction: String, timerSeconds: Int? = nil) {
        self.id = id
        self.index = index
        self.instruction = instruction
        self.timerSeconds = timerSeconds
    }
}

enum RecipeDifficulty: String, Codable, Sendable, CaseIterable {
    case easy, medium, hard

    var label: String {
        switch self {
        case .easy:   return "Easy"
        case .medium: return "Medium"
        case .hard:   return "Hard"
        }
    }
}

// One-shot palette spec — cards rotate through these so a stack of
// generations doesn't look like clones. Kept as raw enum so it serializes.
enum RecipePalette: String, Codable, Sendable, CaseIterable {
    case sunset        // pink → orange (default)
    case grove         // greens
    case ocean         // blues
    case berry         // purples
    case ember         // deep oranges

    static func auto(for index: Int) -> RecipePalette {
        let all = RecipePalette.allCases
        return all[index % all.count]
    }
}
